ок = 0
for н, к, ч in В:
    а = п.Аналіз({"синтетика": ast.parse(к)}, {"відповідь_моделі"}, set(), {}).виконати()
    є = [м[3][-35:] for м in п.Структура(а).зміни_обʼєкта()]
    ок += len(є) == ч
    print("ОК " if len(є)==ч else "ХИБА", len(є), "/", ч, "—", н, є if len(є)!=ч else "")
print("разом", ок, "з", len(В))
